// kernel-worker.js — module Web Worker that hosts the Wolfram Language kernel:
// Pyodide (CDN) + Mathics3 & friends (self-hosted, engine/wheels/) + our wlkernel package (engine/wlkernel/).
// Talks to kernel-client.js:   in:  {id, op, args}      out: {id, ok, result|error} · {type:'progress', …}
// What gets loaded is described by engine/manifest.json (generated by dev/build-engine.mjs).

const ENGINE = new URL('../engine/', import.meta.url);
const CACHE = 'wolframlab-engine-v1';
const post = (m) => self.postMessage(m);

const P1 = 'Descargando Python…';
const P2 = 'Cargando SymPy…';
const P3 = 'Arrancando el kernel de Wolfram Language…';
// progress(phase, pct, cap): pct = done so far, cap = where the bar may creep to before the next report.
const progress = (phase, pct, cap) => post({ type: 'progress', phase, pct, cap: cap ?? pct });

let py = null;
let api = null;
let manifest = null;

// ---------------------------------------------------------------------------------------------- downloads
let cachePromise = null;
function openCache() {
  if (!cachePromise) {
    cachePromise = (async () => {
      try { return self.caches ? await self.caches.open(CACHE) : null; } catch { return null; }
    })();
  }
  return cachePromise;
}

const dl = { done: 0, total: 1 };
function reportDownload() {
  progress(P1, 0.02 + 0.36 * Math.min(1, dl.done / dl.total), 0.4);
}

// Fetch as ArrayBuffer through Cache Storage (immutable, versioned URLs only), counting bytes for the bar.
async function fetchBytes(url, { cache = true, expect = 0 } = {}) {
  url = String(url);
  const store = cache ? await openCache() : null;
  let res = null;
  if (store) { try { res = await store.match(url); } catch { res = null; } }
  const hit = !!res;
  if (!res) {
    res = await fetch(url, cache ? {} : { cache: 'no-cache' });
    if (!res.ok) throw new Error(`HTTP ${res.status} al descargar ${url.split('/').pop()}`);
    if (store) { try { await store.put(url, res.clone()); } catch { /* quota: ignore */ } }
  }
  let buf;
  if (res.body && expect && !hit) {
    const reader = res.body.getReader();
    const chunks = [];
    let n = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value); n += value.length; dl.done += value.length; reportDownload();
    }
    dl.done += Math.max(0, expect - n);
    const out = new Uint8Array(n);
    let o = 0;
    for (const c of chunks) { out.set(c, o); o += c.length; }
    buf = out.buffer;
  } else {
    buf = await res.arrayBuffer();
    dl.done += expect;
  }
  reportDownload();
  return buf;
}

async function pruneCache(keep) {
  const store = await openCache();
  if (!store) return;
  try {
    for (const req of await store.keys()) if (!keep.has(req.url)) await store.delete(req);
  } catch { /* ignore */ }
}

// ---------------------------------------------------------------------------------------------- python side
const BOOT = `
import importlib, json, sys
importlib.invalidate_caches()
import wlboot
wlboot.install()

def _wl_boot(report):
    global K
    import importlib as il
    seen = [0]
    orig = il.import_module
    def import_module(name, package=None):
        if name.startswith("mathics.builtin"):
            seen[0] += 1
            if seen[0] % 6 == 0:
                report(min(1.0, seen[0] / 215.0))
        return orig(name, package)
    il.import_module = import_module
    try:
        from mathics.core.load_builtin import import_and_load_builtins
        from wlkernel import core
        core._ensure_loaded()
        report(2.0)
        K = core.Kernel()
    finally:
        il.import_module = orig

def _wl_run(code):
    return K.run_cell_json(code)

def _wl_check(spec_json):
    return K.check(spec_json)

def _wl_manipulate(mid, values_json):
    return K.manipulate_json(mid, values_json)

def _wl_reset():
    K.reset_user()

def _wl_symbols():
    r = K.eval_code('Names["System\`*"]')
    out = []
    for e in getattr(r, "elements", ()):
        s = getattr(e, "value", None)
        if isinstance(s, str):
            out.append(s.split("\`")[-1])
    return json.dumps(out)

def _wl_defined():
    """Global\` symbols that currently have a definition (the notebook paints them black instead of blue)."""
    out = []
    try:
        for name, d in K.defs.user.items():
            if not name.startswith("Global\`") or name.count("\`") != 1:
                continue
            for attr in ("ownvalues", "downvalues", "subvalues", "upvalues", "nvalues", "defaultvalues"):
                if getattr(d, attr, None):
                    out.append(name[7:])
                    break
    except Exception:
        pass
    return json.dumps(out)
`;

async function init() {
  const t0 = performance.now();
  const marks = {};
  const mark = (k) => { marks[k] = Math.round(performance.now() - t0); };
  progress(P1, 0.01, 0.05);
  manifest = await (await fetch(new URL('manifest.json', ENGINE), { cache: 'no-cache' })).json();
  const v = '?v=' + manifest.version;
  const pyo = manifest.pyodide;
  const pure = manifest.cdn.pure;
  // Rough byte budget of what we download ourselves (pyodide core + numpy are fetched by Pyodide itself).
  dl.total = pure.reduce((s, p) => s + (p.bytes || 300000), 0) + (manifest.bundle ? manifest.bundle.bytes : 4500000) + 200000;

  // Everything that can download in parallel starts now.
  const keep = new Set();
  const url = (rel) => { const u = String(new URL(rel, ENGINE)); keep.add(u); return u; };
  const pureP = pure.map((p) => {
    const u = pyo.pycURL + p.pyc; keep.add(u);
    return fetchBytes(u, { expect: p.bytes || 300000 }).catch((e) => ({ failed: e }));
  });
  const bundleP = manifest.bundle
    ? fetchBytes(url(manifest.bundle.file), { expect: manifest.bundle.bytes }).catch((e) => ({ failed: e }))
    : Promise.resolve({ failed: new Error('no bundle') });
  const bootP = fetchBytes(url(manifest.boot + v), { cache: false });
  // (GitHub Pages without a .nojekyll file refuses to serve files starting with "_": an empty __init__.py is fine.)
  const engineP = manifest.engine.files.map((f) => fetchBytes(url(manifest.engine.dir + f + v), { cache: false })
    .catch((e) => { if (f === '__init__.py') return new ArrayBuffer(0); throw e; }));

  const { loadPyodide } = await import(/* @vite-ignore */ pyo.indexURL + 'pyodide.mjs');
  const quiet = (s) => { if (!/Not able to load|mathics\.builtin loads from|^\s*$|^ImportError/.test(s)) console.log('[py]', s); };
  // stdLibURL: the byte-compiled standard library of the same release (no .py → bytecode step while booting)
  py = await loadPyodide({ indexURL: pyo.indexURL, stdLibURL: pyo.pycURL + 'python_stdlib.zip', stdout: quiet, stderr: quiet });
  mark('pyodide');
  if (py.version !== pyo.version) console.warn('[kernel] Pyodide', py.version, '≠', pyo.version);
  const numpyP = py.loadPackage(manifest.cdn.binary, { messageCallback: () => {} });

  const sp = py.runPython('import site; site.getsitepackages()[0]');
  const fallback = [];
  for (let i = 0; i < pure.length; i++) {
    const buf = await pureP[i];
    if (buf.failed) { fallback.push(pure[i].name); continue; }
    try {
      if (pure[i].zip) { // byte-compiled wheel straight onto sys.path (zipimport): no unpacking of ~1500 files
        py.FS.mkdirTree('/wl');
        py.FS.writeFile(`/wl/${pure[i].name}.zip`, new Uint8Array(buf));
        py.runPython(`import sys; sys.path.insert(0, "/wl/${pure[i].name}.zip")`);
      } else py.unpackArchive(buf, 'wheel');
    } catch (e) { console.warn('[kernel]', pure[i].name, e); fallback.push(pure[i].name); }
  }
  await numpyP;
  if (fallback.length) await py.loadPackage(fallback, { messageCallback: () => {} });

  let bundled = false;
  const bundle = await bundleP;
  if (!bundle.failed) {
    try { py.unpackArchive(bundle, 'zip', { extractDir: sp }); bundled = true; } catch (e) { console.warn('[kernel] bundle', e); }
  }
  if (!bundled) { // slower path: the original wheels (plain .py, compiled by the browser at import)
    for (const w of manifest.wheels) py.unpackArchive(await fetchBytes(url(w.file), { expect: w.bytes }), 'wheel');
  }
  py.FS.writeFile(`${sp}/wlboot.py`, new Uint8Array(await bootP));
  py.FS.mkdirTree(`${sp}/wlkernel`);
  for (let i = 0; i < engineP.length; i++) {
    py.FS.writeFile(`${sp}/wlkernel/${manifest.engine.files[i]}`, new Uint8Array(await engineP[i]));
  }
  // A manifest that is older than the engine (someone added a module and did not re-run build-engine.mjs)
  // must not brick the site: (a) a dev server that lists directories tells us the real file list,
  // (b) a missing wlkernel module is fetched on demand when Python asks for it (see the retry loop below).
  const have = new Set(manifest.engine.files);
  const fetchEngineFile = async (name) => {
    const res = await fetch(new URL(manifest.engine.dir + name, ENGINE), { cache: 'no-cache' });
    if (!res.ok) return false;
    py.FS.writeFile(`${sp}/wlkernel/${name}`, new Uint8Array(await res.arrayBuffer()));
    have.add(name);
    return true;
  };
  try {
    const res = await fetch(new URL(manifest.engine.dir, ENGINE), { cache: 'no-cache' });
    const html = res.ok && /text\/html/.test(res.headers.get('content-type') || '') ? await res.text() : '';
    if (/Directory listing/i.test(html)) {
      for (const m of html.matchAll(/href="([\w.-]+\.(?:py|wl|m|json|txt))"/g)) if (!have.has(m[1])) { console.warn('[kernel] manifest.json desactualizado: falta', m[1]); await fetchEngineFile(m[1]); }
    }
  } catch { /* not a listing server: fine */ }
  pruneCache(keep);

  mark('files');
  progress(P2, 0.42, 0.54);
  await py.runPythonAsync('import numpy, mpmath, sympy');
  mark('sympy');
  progress(P3, 0.55, 0.62);
  py.runPython(BOOT);
  const boot = py.globals.get('_wl_boot');
  const report = (f) => (f > 1 ? progress(P3, 0.86, 0.985) : progress(P3, 0.56 + 0.3 * f, 0.56 + 0.3 * f + 0.05));
  for (let attempt = 0; ; attempt++) {
    try { boot(report); break; } catch (e) {
      const m = /cannot import name '(\w+)' from 'wlkernel'|No module named 'wlkernel\.(\w+)'/.exec(String(e && e.message));
      const name = m && (m[1] || m[2]) + '.py';
      if (!name || have.has(name) || attempt > 12 || !(await fetchEngineFile(name))) throw e;
      console.warn('[kernel] manifest.json desactualizado: cargado', name, '(ejecuta node site/dev/build-engine.mjs)');
      py.runPython('import importlib, sys; importlib.invalidate_caches(); [sys.modules.pop(k) for k in list(sys.modules) if k == "wlkernel" or k.startswith("wlkernel.")]');
    }
  }
  boot.destroy();
  api = {};
  for (const n of ['run', 'check', 'manipulate', 'reset', 'symbols', 'defined']) api[n] = py.globals.get('_wl_' + n);
  progress(P3, 1, 1);
  mark('kernel');
  return { version: manifest.version, pyodide: py.version, bundled, ms: marks };
}

function defined() {
  try { return JSON.parse(api.defined()); } catch { return []; }
}

const OPS = {
  init,
  run: ({ code }) => { const r = JSON.parse(api.run(String(code ?? ''))); r.defined = defined(); return r; },
  check: ({ spec }) => { const r = JSON.parse(api.check(JSON.stringify(spec ?? {}))); r.defined = defined(); return r; },
  manipulate: ({ id, values }) => JSON.parse(api.manipulate(id, JSON.stringify(values ?? {}))),
  reset: () => { api.reset(); return { defined: [] }; },
  symbols: () => JSON.parse(api.symbols()),
};

self.onmessage = async (ev) => {
  const { id, op, args } = ev.data || {};
  try {
    if (!OPS[op]) throw new Error('operación desconocida: ' + op);
    if (op !== 'init' && !api) throw new Error('el kernel no está listo');
    post({ id, ok: true, result: await OPS[op](args || {}) });
  } catch (e) {
    post({ id, ok: false, error: String((e && e.message) || e).slice(-1200) });
  }
};
